package com.nigson.acceptance.nigeria;
import com.nigson.commerce.payment.internal.infrastructure.external.paystack.PaystackAdapter;
import com.nigson.shared.security.ProviderHttp;
import com.nigson.shared.events.EventCodec;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.Test;
import java.net.InetSocketAddress;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.assertj.core.api.Assertions.*;
class NigeriaKoboTest {
 @Test void minorUnitsAreExactAndFractionalKoboFails(){assertThat(PaystackAdapter.kobo("1234.56")).isEqualTo(123456);assertThat(PaystackAdapter.kobo("0.01")).isEqualTo(1);assertThat(PaystackAdapter.kobo("999999999999999.99")).isEqualTo(99999999999999999L);for(String amount:List.of("1234.567","0","-1","1e2","1.000","1,234.56"," 1.00","1000000000000000"))assertThatThrownBy(()->PaystackAdapter.kobo(amount)).hasMessage("NGN_AMOUNT_INVALID");}
 @Test void actualHttpInitializationSendsKoboAndWrongProviderCurrencyCannotVerify()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var amounts=new HashMap<String,Long>();var wrong=new AtomicBoolean(false);server.createContext("/transaction/initialize",exchange->{assertThat(exchange.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer sk_mock_nigson");var body=EventCodec.JSON.readTree(exchange.getRequestBody().readAllBytes());assertThat(body.path("currency").asString()).isEqualTo("NGN");assertThat(body.path("amount").isIntegralNumber()).isTrue();amounts.put(body.path("reference").asString(),body.path("amount").asLong());byte[] reply=EventCodec.JSON.writeValueAsBytes(Map.of("status",true,"data",Map.of("reference",body.path("reference").asString(),"authorization_url","http://paystack-mock/offline-hosted","access_code","synthetic-offline-only")));exchange.sendResponseHeaders(200,reply.length);exchange.getResponseBody().write(reply);exchange.close();});server.createContext("/transaction/verify/",exchange->{String ref=exchange.getRequestURI().getPath().substring("/transaction/verify/".length());byte[] reply=EventCodec.JSON.writeValueAsBytes(Map.of("status",true,"data",Map.of("reference",ref,"amount",amounts.get(ref),"currency",wrong.get()?"USD":"NGN","domain","test","status","pending")));exchange.sendResponseHeaders(200,reply.length);exchange.getResponseBody().write(reply);exchange.close();});server.start();try{var adapter=new PaystackAdapter("test",ProviderHttp.Mode.MOCK,"http://127.0.0.1:"+server.getAddress().getPort(),"sk_mock_nigson");adapter.initialize("synthetic-ngn-kobo","synthetic@example.invalid","1234.56");assertThat(amounts.get("synthetic-ngn-kobo")).isEqualTo(123456L);assertThatThrownBy(()->adapter.initialize("fractional","synthetic@example.invalid","1234.567")).hasMessage("NGN_AMOUNT_INVALID");assertThat(amounts).hasSize(1);assertThat(adapter.verify("synthetic-ngn-kobo",123456).path("status").asString()).isEqualTo("pending");wrong.set(true);assertThatThrownBy(()->adapter.verify("synthetic-ngn-kobo",123456)).hasMessage("PAYSTACK_VERIFICATION_MISMATCH");}finally{server.stop(0);}}
}
